export const GLOSSARY = [
    { term: "Asset turnover", def: "Revenue divided by average total assets. Shows how efficiently assets create sales." },
    { term: "Book value per share", def: "Shareholders’ equity divided by number of shares outstanding." },
    { term: "Capex", def: "Capital expenditure. Cash spent on buying or upgrading long-term assets." },
    { term: "CAGR", def: "Compound annual growth rate: the smoothed yearly growth between two points in time." },
    { term: "Capital employed", def: "Funds used in the business, commonly equity plus borrowings." },
    { term: "Cash conversion cycle", def: "Inventory days plus receivable days minus payable days." },
    { term: "CFO", def: "Cash flow from operations: cash generated by the core business." },
    { term: "COGS", def: "Cost of goods sold. Direct costs of producing what was sold." },
    { term: "Consolidated", def: "Financials combining the parent and all its subsidiaries." },
    { term: "Contingent liability", def: "A possible obligation that depends on a future event, disclosed in the notes." },
    { term: "Current ratio", def: "Current assets divided by current liabilities. A short-term liquidity measure." },
    { term: "CWIP", def: "Capital work in progress. Assets under construction not yet in use." },
    { term: "D/E ratio", def: "Total borrowings divided by shareholders’ equity." },
    { term: "Depreciation", def: "Systematic allocation of an asset’s cost over its useful life. Non-cash." },
    { term: "DuPont analysis", def: "Splits ROE into net margin, asset turnover and financial leverage." },
    { term: "EBIT", def: "Earnings before interest and tax." },
    { term: "EBITDA", def: "Earnings before interest, tax, depreciation and amortisation." },
    { term: "EPS", def: "Earnings per share: PAT attributable to shareholders divided by shares outstanding." },
    { term: "Enterprise value (EV)", def: "Market cap plus debt minus cash. The price of the whole business." },
    { term: "FCF", def: "Free cash flow: cash from operations minus capex." },
    { term: "FII / FPI", def: "Foreign institutional or portfolio investors." },
    { term: "DII", def: "Domestic institutional investors such as mutual funds and insurers." },
    { term: "Goodwill", def: "Premium paid over the fair value of net assets in an acquisition." },
    { term: "Ind AS", def: "Indian Accounting Standards, converged with IFRS, used by listed companies." },
    { term: "Interest coverage", def: "EBIT divided by interest expense. How comfortably profit covers interest." },
    { term: "Intrinsic value", def: "An estimate of what a business is truly worth based on its fundamentals." },
    { term: "Margin of safety", def: "The gap between intrinsic value and purchase price, a buffer against error." },
    { term: "Market capitalisation", def: "Share price multiplied by total shares outstanding." },
    { term: "Minority interest", def: "The share of subsidiaries’ profit and equity owned by outside shareholders." },
    { term: "Moat", def: "A durable competitive advantage that protects a company’s profits." },
    { term: "Net debt", def: "Borrowings minus cash and equivalents." },
    { term: "NPA", def: "Non-performing asset. A loan where payments are overdue for over 90 days." },
    { term: "OPM", def: "Operating profit margin: EBITDA divided by revenue." },
    { term: "P/B", def: "Price to book value." },
    { term: "P/E", def: "Price divided by earnings per share." },
    { term: "PAT", def: "Profit after tax." },
    { term: "PBT", def: "Profit before tax." },
    { term: "PEG", def: "P/E divided by expected EPS growth rate." },
    { term: "Pledged shares", def: "Shares promoters have offered as collateral for loans." },
    { term: "Promoter", def: "The person or group that founded or controls the company." },
    { term: "Quick ratio", def: "Liquid assets (excluding inventory) divided by current liabilities." },
    { term: "Reserves", def: "Retained profits and other accumulated surpluses within equity." },
    { term: "ROA", def: "Return on assets: PAT divided by average total assets." },
    { term: "ROCE", def: "Return on capital employed: EBIT divided by capital employed." },
    { term: "ROE", def: "Return on equity: PAT divided by average shareholders’ equity." },
    { term: "Standalone", def: "Financials of the parent company only." },
    { term: "TTM", def: "Trailing twelve months: the sum of the last four reported quarters." },
    { term: "Working capital", def: "Current operating assets minus current operating liabilities." },
    { term: "YoY / QoQ", def: "Year-on-year and quarter-on-quarter comparisons." },
];
